# numbers_offformation.jl: the macros of E111 (results/e111_offformation.json, HPG runs), off-formation starts
# with intra-team diffusion, written to preamble/numbers_offformation.tex. Not registered with gen_numbers.jl;
# main.tex inputs the generated file with \InputIfFileExists.
#
#   julia --project=env scripts/resolution/numbers_offformation.jl
#
# Macro names: \cnOff<Arm><Metric><Level><Size>
#   Arm     Team (team input only), Dif (+ diffusion, gain 1/(2 d_c)), Opt (+ diffusion, spectrum-tuned PD gains),
#           Lqr (Algorithm 1, LQR toward the projected state), Cent (centralized, converged)
#   Metric  Cost (closed-loop cost over centralized, median over seeds), Fin (final spread over initial, median),
#           Late (median spread over the second half over initial, median over seeds), Tone / Tfive (median first
#           step with spread <= 1% / 5% of initial, "none" if no seed reached it), Clip (percent of member-steps
#           with the applied input clipped, median), Ms (median wall ms per step, median over seeds)
#   Level   A, B, C (sigma = 0.1, 0.3, 1 edge lengths), Dist (sigma 0.3 plus velocity kicks every step)
#   Size    S (256 vehicles), K (1024 vehicles)

using JSON, Printf

function sci(x; d = 1)
    x == 0 && return "0"
    e = floor(Int, log10(abs(x))); m = x / 10.0^e
    s = @sprintf("%.*f", d, m)
    if parse(Float64, s) >= 10; m /= 10; e += 1; s = @sprintf("%.*f", d, m); end
    return "\\ensuremath{$(s)\\times10^{$(e)}}"
end
sig(x; n = 2) = (s = @sprintf("%.*g", n, x); occursin("e", s) ? sci(x) : s)
f3(x) = @sprintf("%.3f", x)
f2(x) = @sprintf("%.2f", x)
sig3k(x) = (s = @sprintf("%#.3g", x); occursin("e", s) ? sci(x) : s)   # three significant digits, trailing zeros kept (1.00)
med(d) = d === nothing ? nothing : d["median"]

function write_offformation_numbers(root = normpath(joinpath(@__DIR__, "..", "..")))
    src = joinpath(root, "results", "e111_offformation.json")
    E = JSON.parsefile(src)
    lines = String["% GENERATED by scripts/resolution/numbers_offformation.jl from results/e111_offformation.json; do not edit by hand.",
                   "% Regenerate with `julia --project=env scripts/resolution/numbers_offformation.jl`.", ""]
    put(name, val, meaning) = (push!(lines, "% $meaning"); push!(lines, "\\newcommand{\\$name}{$val}"))
    sizes = Dict("256" => "S", "1024" => "K")
    levels = Dict("s0.1" => "A", "s0.3" => "B", "s1" => "C", "dist" => "Dist")
    arms = Dict("team" => "Team", "diffuse" => "Dif", "diffuse_opt" => "Opt", "alg1" => "Lqr", "central" => "Cent")
    for (n, S) in sort(collect(E["sizes"]); by = first)
        haskey(sizes, n) || continue
        z = sizes[n]
        put("cnOffN$z", n, "vehicles")
        put("cnOffSeeds$z", string(length(S["seeds"])), "seeds")
        put("cnOffTeams$z", string(round(Int, S["teams"]["median"])), "teams (planted squads), median over seeds")
        put("cnOffTeamMin$z", string(round(Int, S["team_size_min"])), "smallest team")
        put("cnOffTeamMax$z", string(round(Int, S["team_size_max"])), "largest team")
        put("cnOffAep$z", sci(max(S["aep_spread_max"], 1e-16)), "largest almost-equitable spread (0 = exact)")
        put("cnOffDisc$z", string(S["teams_disconnected_inside"]), "teams disconnected inside the formation graph")
        put("cnOffEll$z", f2(S["edge_length_median"]["median"]), "median edge length inside teams (m)")
        put("cnOffRhoDif$z", f3(S["slowest_mode_rho_diffuse_median"]), "slowest-mode rate per step, diffusion gain 1/(2 d_c), median over teams")
        put("cnOffRhoOpt$z", f3(S["slowest_mode_rho_opt_median"]), "slowest-mode rate per step, tuned diffusion, median over teams")
        put("cnOffRhoLqr$z", f3(S["alg1_rho_max"]), "rate per step of the LQR correction (all modes), largest type")
        put("cnOffRhoStab$z", f3(S["stability_rho_max"]), "max over s in (0,1] of rho(A - s B K), all types (< 1: stable)")
        put("cnOffJobs$z", join(S["jobs"], ", "), "SLURM job")
        for (lname, L) in S["levels"]
            haskey(levels, lname) || continue
            lv = levels[lname]
            for (arm, C) in L
                haskey(arms, arm) || continue
                a = arms[arm]
                tag = "$n vehicles, level $lname, arm $arm"
                C["cost_ratio"] === nothing || arm == "central" || put("cnOff$(a)Cost$(lv)$(z)", sig3k(C["cost_ratio"]["median"]), "$tag: closed-loop cost over centralized, median")
                get(C, "cost_ratio_alg1", nothing) === nothing || arm in ("alg1", "central") ||
                    put("cnOff$(a)CostLqr$(lv)$(z)", sig(C["cost_ratio_alg1"]["median"]; n = 3), "$tag: closed-loop cost over that of Algorithm 1, median")
                put("cnOff$(a)Fin$(lv)$(z)", sig(C["spread_final_rel"]["median"]), "$tag: final spread over initial, median")
                put("cnOff$(a)Late$(lv)$(z)", sig(C["spread_late_median_rel"]["median"]), "$tag: second-half spread over initial, median")
                put("cnOff$(a)Tone$(lv)$(z)", C["t1pct_reached"] == 0 ? "none" : string(round(Int, C["t1pct_step"]["median"])),
                    "$tag: median first step at 1% of the initial spread ($(C["t1pct_reached"]) seeds reached it)")
                put("cnOff$(a)Tfive$(lv)$(z)", C["t5pct_reached"] == 0 ? "none" : string(round(Int, C["t5pct_step"]["median"])),
                    "$tag: median first step at 5% of the initial spread ($(C["t5pct_reached"]) seeds reached it)")
                put("cnOff$(a)Clip$(lv)$(z)", sig(100 * C["clipped_frac"]["median"]), "$tag: percent of member-steps clipped, median")
                put("cnOff$(a)Ms$(lv)$(z)", sig(C["t_step_ms_median"]; n = 3), "$tag: median ms per step")
                @assert C["violations_applied_total"] == 0
                @assert C["max_input_ratio_applied"] <= 1 + 1e-9
            end
        end
    end
    for (n, P) in get(E, "timing_probe", Dict())
        haskey(sizes, n) || continue
        for (arm, ms) in P["t_step_ms_median"]
            arm == "central" && put("cnOffProbeCentS$(sizes[n])", sig(ms / 1e3; n = 2), "timing probe, $n vehicles: median s per step of converged centralized MPC")
            haskey(arms, arm) && put("cnOffProbe$(arms[arm])Ms$(sizes[n])", sig(ms; n = 3), "timing probe, $n vehicles, $(P["steps"]) steps, job $(P["job"]): median ms per step of $arm")
        end
    end
    out = joinpath(root, "preamble", "numbers_offformation.tex")
    write(out, join(lines, "\n") * "\n"); println("wrote ", out)
end

if abspath(PROGRAM_FILE) == @__FILE__
    write_offformation_numbers()
end
